#!/usr/bin/env bash
# QC2 (X211-X214): share cross-check (X211 period-end count after a split, X212 allotment before the results,
# X213 trust-held treasury shares), ATTRIBUTION_BY_EPS (X214), PDF corrections and resolutions of filer errors.
# Ids are from the snapshot of 2026-11-17 (after phase 1); a resolve of an id already closed fails harmlessly (set +e).
set -u
PY="${PY:-python}"
D="${D:-data}"

# 1. Parser 0.10.7 (X213 Reg. 31 'Others' holder rows, X214): re-parse every results and Reg. 31 filing, then promote.
#    promote re-runs the share cross-check (closes CROSS_CHECK_FAILED that now agree: expected 60 of 209 open) and
#    the annual share check (ANNUAL_SHARE_COUNT_DIFFERS: expected 10 of 70, IOC / BPCL / SESHAPAPER), and the
#    re-parsed results close ATTRIBUTION_WITHHELD findings recovered by X214 (expected 108 of 256).
#    If a staging batch for 0.10.7 already exists from an earlier build, delete it first (restage does not overwrite).
$PY -m financials --data-dir "$D" restage --category RESULTS_XBRL
$PY -m financials --data-dir "$D" restage --category SHP_XBRL
$PY -m financials --data-dir "$D" promote
$PY -m financials --data-dir "$D" audit-annual

set +e
# 2. PDF corrections (owner decision B): Beta Drugs Q1 / Q2 / H1 FY27 consolidated owners / NCI (QC2_corrections.py).
$PY ops/live/QC2_corrections.py "$D/market.duckdb"

